import json
import sys
from argparse import ArgumentParser

def main(argv=None):
    parser = ArgumentParser(description='Expense Log CLI')
    parser.add_argument('--file', required=True, help='Path to the expense log file')
    parser.add_argument('command', choices=['add', 'list', 'total'], help='Command to execute')
    parser.add_argument('amount', type=int, nargs='?', help='Amount in cents for add command')
    parser.add_argument('category', nargs='?', help='Category for add command')
    args = parser.parse_args(argv)

    if args.command == 'add':
        if args.amount <= 0 or not args.category:
            sys.stderr.write('Invalid input: amount must be positive and category must not be empty\n')
            sys.exit(1)
        add_expense(args.file, args.amount, args.category)
        print('ADDED')
    elif args.command == 'list':
        list_expenses(args.file)
    elif args.command == 'total':
        total = get_total(args.file)
        print(total)

def add_expense(file_path, amount, category):
    try:
        with open(file_path, 'r') as file:
            expenses = json.load(file)
    except FileNotFoundError:
        expenses = []
    except json.JSONDecodeError:
        sys.stderr.write('Malformed JSON file\n')
        sys.exit(1)

    expenses.append({'amount': amount, 'category': category})
    with open(file_path, 'w') as file:
        json.dump(expenses, file, indent=4)

def list_expenses(file_path):
    try:
        with open(file_path, 'r') as file:
            expenses = json.load(file)
    except FileNotFoundError:
        expenses = []
    except json.JSONDecodeError:
        sys.stderr.write('Malformed JSON file\n')
        sys.exit(1)

    for expense in expenses:
        print(f'{expense['amount']} {expense['category']}')

def get_total(file_path):
    try:
        with open(file_path, 'r') as file:
            expenses = json.load(file)
    except FileNotFoundError:
        return 0
    except json.JSONDecodeError:
        sys.stderr.write('Malformed JSON file\n')
        sys.exit(1)

    return sum(expense['amount'] for expense in expenses)

if __name__ == '__main__':
    main()
